// Написан вручную (API: rpc/questionnaire_for_me от имени пользователя — генератор так не умеет).
// spec: .qa/e2e/specs/questionnaire.md 1.1–1.2 · кейсы .qa/tests/questionnaire/QN-01, QN-02 · тикет #d20b68
// Только чтение. Аккаунты с известным треком: new10 — «חילוני/ת», new05 — «מסורתי \ דתי».
// Не проверен на живой странице (записан 10.11 без прогона) — сверить при первом /qa-regress.
import { test, expect } from '../../fixtures';
import { captureApi, rpc, type Row } from '../_shared/api';
import { saveSession } from '../_shared/session';

const GENERAL = ['height_kids', 'lifestyle', 'looking_for'];

async function stepsFor(page: import('@playwright/test').Page): Promise<Row[]> {
  const api = await captureApi(page, '/');
  const res = await rpc(api, 'questionnaire_for_me', {});
  expect(res.status(), `questionnaire_for_me: ${await res.text()}`).toBe(200);
  const body = await res.json();
  expect(Array.isArray(body), 'ответ — список шагов').toBeTruthy();
  return body as Row[];
}

const sorts = (rows: Row[]) => rows.map((r) => Number(r.sort));
const isAscending = (xs: number[]) => xs.every((x, i) => i === 0 || xs[i - 1] <= x);

test.describe('מנוע שאלונים מותאמי קהל — треки', () => {
  test('Светский трек — 3 общих шага @iphone @prod-safe (#d20b68)', async ({ asUser }) => {
    const page = await asUser('new10');
    try {
      const rows = await stepsFor(page);
      // AC 2, 5: не-דתי → общий трек: height_kids, lifestyle, looking_for, track = null.
      expect(rows.map((r) => r.key)).toEqual(GENERAL);
      expect(rows.map((r) => r.track ?? null)).toEqual([null, null, null]);
      expect(isAscending(sorts(rows)), 'шаги по возрастанию sort').toBeTruthy();
    } finally {
      await saveSession(page, 'new10');
    }
  });

  test('Религиозный трек — 5 религиозных + 3 общих @iphone @prod-safe (#d20b68)', async ({ asUser }) => {
    const page = await asUser('new05');
    try {
      const rows = await stepsFor(page);
      // AC 3, 5 + чек-лист r8: «מסורתי \ דתי» → 5 шагов track=religious, затем 3 общих.
      expect(rows).toHaveLength(8);
      expect(rows.slice(0, 5).map((r) => r.track)).toEqual(Array(5).fill('religious'));
      expect(rows.slice(5).map((r) => r.key)).toEqual(GENERAL);
      expect(rows.slice(5).map((r) => r.track ?? null)).toEqual([null, null, null]);
      expect(isAscending(sorts(rows)), 'шаги по возрастанию sort').toBeTruthy();
    } finally {
      await saveSession(page, 'new05');
    }
  });
});
